		#region Grid_ColourDeciding

		void Grid_ColourDeciding(object sender, ColourDecidingEventArgs e)
		{
			var inventoryLine = e.ObjectAtRow as WhsReceiveLine;
			if (inventoryLine != null)
			{
				if (inventoryLine.WE_TransactionQuantity > inventoryLine.WE_ClientOrderedUnits)
				{
					e.Colour = Color.LightGreen;
				}
				else if (inventoryLine.WE_TransactionQuantity < inventoryLine.WE_ClientOrderedUnits)
				{
					e.Colour = Color.LightSalmon;
				}
			}
		}

		#endregion

		#region OnProductChanged

		void OnProductChanged(object sender, EventArgs args)
		{
			var receiveLine = sender as WhsReceiveLine;
			if (receiveLine?.IsTemporaryProductGuid ?? false)
			{
				// Handles override of Product Code during WE_OP = ZGuid.Invalid for temp products.
				receiveLine.ProductCode = FieldInvalidTextMemory.GetInvalidText(receiveLine, WhsReceiveLine.Schema.WE_OP);
			}
		}

