		void ShowInventoryEditForm(WhsReceiveLine inventoryLine)
		{
			if (Docket.HasChanges)
			{
				Globals.Message.ShowWarning(Res.GetString("d70744ab-af12-4e7d-8655-b9d09191d02e", "Please save this Receipt before going to the Inventory Form"));
			}
			else
			{
				var form = (InventoryForm)ZControllerFactory.Create(ControllerIDs.WhsInventory).ShowEditForm(inventoryLine);
				if (form != null)
				{
					var inventoryFromForm = (WhsDocketLine)form.BusinessEntity;
					inventoryFromForm.IsInventoryEditForm = true;
					inventoryFromForm.Inventory[0].IsInventoryEditForm = true;
				}
			}
		}

