		#region SetGridSideControlVisibilityAndWidth

		void SetGridSideControlVisibilityAndWidth(UserControl gridSideUserControl)
		{
			gridSideUserControl.Visible = !gridSideUserControl.Visible;

			const int extraWidth = 7;
			if (gridSideUserControl.Visible)
			{
				ControlDpiScalingHelper.SetWidth(ref LinesGrid, Width - gridSideUserControl.Width - ControlDpiScalingHelper.ScaleToCurrentDpiX(extraWidth), false);
			}
			else
			{
				ControlDpiScalingHelper.SetWidth(ref LinesGrid, Width, false);
			}

			if (serialNumberMenuItem != null)
			{
				serialNumberMenuItem.Caption = SerialNumberControl.Visible ?
					ResString.GetMultilingualString("9C8079BB-295E-4FC7-8D87-04EE933266CF", "Hide &Serials") :
					ShowSerialNumberCaption;
