		#region OnLoad

		protected override void OnLoad(EventArgs e)
		{
			base.OnLoad(e);

			if (LinesGrid.ListManager != null)
			{
				LinesGrid.ListManager.ListChanged += List_ListChanged;
			}
		}

		void List_ListChanged(object sender, ListChangedEventArgs e)
		{
			if (e.ListChangedType == ListChangedType.ItemAdded)
			{
				var listManager = sender as CurrencyManager;
				var receiveLines = listManager?.List as WhsReceiveLineCollection;

				if (receiveLines != null)
				{
					var inventory = (WhsReceiveLine)receiveLines.ElementAtOrDefault(e.NewIndex);
					if (inventory != null)
					{
						PullInvalidProductCodeFromBusiness(inventory);
					}
				}
			}
		}

		void PullInvalidProductCodeFromBusiness(WhsReceiveLine receiveLine)
		{
			if (receiveLine.IsTemporaryProduct)
			{
				string currentErrorPartCode = FieldInvalidTextMemory.GetInvalidText(receiveLine, WhsDocketLineSchema.WE_OP.Name);
				string partCode = receiveLine.ProductCode;

				if (currentErrorPartCode != partCode)
				{
					FieldInvalidTextMemory.SetInvalidText(receiveLine, WhsDocketLineSchema.WE_OP.Name, partCode);
				}
			}
		}

		#endregion

